mapper.select:
	/*
		StatCodeMapper.selectStatCodeListCount 통계 코드 목록 갯수
	*/
  SELECT COUNT(*) 
  FROM T_TCODE_LIST 
  WHERE DEL_FLAG='N'

    AND COMPANY_CODE = #{companyCode}


	  AND TABLE_CODE = #{tableCode}

	/*
		StatCodeMapper.selectStatCodeList 통계 코드 목록 조회
	*/
  SELECT TABLE_CODE, TABLE_NAME, COMPANY_CODE, USE_YN, DEL_FLAG 
  FROM T_TCODE_LIST
  WHERE DEL_FLAG = 'N'

    AND COMPANY_CODE = #{companyCode}


	  AND TABLE_CODE = #{tableCode}

	ORDER BY COMPANY_CODE, TABLE_CODE, TABLE_NAME
